import InputSelect from "./InputSelect";

export default function InputAggregator() {
  return (
    <InputSelect
      name="aggregatorPartner"
      label="Aggregator partner"
      canAddItems
      message="Select or type your partner"
      options={[
        { value: "Australian Finance Aggregation", label: "Australian Finance Aggregation" },
        { value: "Connective", label: "Connective" },
        { value: "Dealer Business Solutions", label: "Dealer Business Solutions" },
        { value: "Fintelligence", label: "Fintelligence" },
        { value: "NFC / MMSP Group", label: "NFC / MMSP Group" },
        { value: "Platform Group", label: "Platform Group" },
      ]}
    />
  );
}
